class CarPhotoView:public QWidget {
 QPixmap source;bool contain_;
public:
 explicit CarPhotoView(const QString& path,const Json& crop=Json(),int decodeWidth=512,bool contain=false):contain_(contain){
 QImageReader reader(path);reader.setAutoTransform(true);auto dimensions=reader.size();
 if(crop.is_array()&&crop.size()==6&&dimensions==QSize(crop[0].get<int>(),crop[1].get<int>())){
  auto image=reader.read();QRect region(crop[2].get<int>(),crop[3].get<int>(),crop[4].get<int>(),crop[5].get<int>());
  if(!image.isNull()&&image.rect().contains(region))image=image.copy(region);
  source=QPixmap::fromImage(image.scaled(QSize(decodeWidth,decodeWidth*360/512),Qt::KeepAspectRatio,Qt::SmoothTransformation));
 }else{if(dimensions.isValid()){dimensions.scale(decodeWidth,decodeWidth*360/512,Qt::KeepAspectRatio);reader.setScaledSize(dimensions);}source=QPixmap::fromImage(reader.read());}
 setMinimumWidth(190);setFixedHeight(170);setSizePolicy(QSizePolicy::Expanding,QSizePolicy::Expanding);
 }
 QSize decodedSize()const{return source.size();}

protected:
 void paintEvent(QPaintEvent*)override{QPainter p(this);if(property("marketPhoto").toBool()){p.setRenderHint(QPainter::Antialiasing);QPainterPath clip;clip.moveTo(0,height());clip.lineTo(0,6);clip.quadTo(0,0,6,0);clip.lineTo(width()-6,0);clip.quadTo(width(),0,width(),6);clip.lineTo(width(),height());clip.closeSubpath();p.setClipPath(clip);}p.fillRect(rect(),QColor(contain_?"#ffffff":"#e8edeb"));if(source.isNull()){p.setPen(QColor("#748086"));p.drawText(rect(),Qt::AlignCenter,QStringLiteral("Фото недоступно"));return;}p.setRenderHint(QPainter::SmoothPixmapTransform);auto size=source.size();size.scale(this->size(),contain_?Qt::KeepAspectRatio:Qt::KeepAspectRatioByExpanding);QRect target((width()-size.width())/2,(height()-size.height())/2,size.width(),size.height());p.drawPixmap(target,source,source.rect());}
};
