  for(int row=0;row<perekup::Snake::size;++row)for(int col=0;col<perekup::Snake::size;++col)p.fillRect(x+col*cell,y+row*cell,cell,cell,dark?QColor((row+col)%2?"#22362d":"#263c32"):QColor((row+col)%2?"#e4efdf":"#ecf4e7"));
  p.setPen(QPen(dark?QColor(157,192,163,25):QColor(80,120,85,24),.6));for(int n=0;n<=perekup::Snake::size;++n){p.drawLine(x+n*cell,y,x+n*cell,y+side);p.drawLine(x,y+n*cell,x+side,y+n*cell);}p.setPen(QPen(dark?QColor("#6b9a7c"):QColor("#7b9c78"),2));p.setBrush(Qt::NoBrush);p.drawRoundedRect(QRectF(x-1,y-1,side+2,side+2),5,5);
