 perekup::RuntimeHooks runtimeHooks(bool busy=false){perekup::RuntimeHooks hooks;hooks.career=[](Json& state){perekup::tickNativeCareer(state);};hooks.collectors=[busy](Json& state){perekup::tickNativeCollectors(state,randomUnit,busy);};hooks.meeting=[](Json& state){perekup::tickNativeMeeting(state,randomUnit,[](Json& draft,perekup::Money id){auto key=std::to_string(id);auto& risks=draft["marketRisks"]["vehicles"];if(!risks.contains(key))risks[key]=perekup::rollMarketRisk(draft["chat"]["car"],randomUnit);perekup::inspectMarketRisk(risks[key],false,[](perekup::Money){return false;});});};hooks.buyerDelay=[this](const Json& listing){return perekup::nativeListingDelay(session->state,carsById.at(std::to_string(listing.at("carId").get<perekup::Money>())),listing,randomUnit());};hooks.listings=[this](Json& state){perekup::NativeBuyerHooks buyers;buyers.random=randomUnit;buyers.newId=[](){return QUuid::createUuid().toString(QUuid::WithoutBraces).toStdString();};buyers.delay=[&](const Json& listing){return perekup::nativeListingDelay(state,carsById.at(std::to_string(listing.at("carId").get<perekup::Money>())),listing,randomUnit());};buyers.moving=[&](perekup::Money id){auto k=std::to_string(id);const auto& vehicles=state["transport"]["vehicles"];return vehicles.contains(k)&&(vehicles[k].value("place","")=="road"||vehicles[k].value("place","")=="carrier");};buyers.tuningEffect=[](const Json&,const Json&){return Json{{"amount",0},{"text",""}};};perekup::tickNativeListings(state,carsById,catalog.at("tradeCars"),buyers);};return hooks;}
