 void garageApp(){auto body=new QWidget;auto layout=new QVBoxLayout(body);auto upgrade=button(QStringLiteral("Расширить гараж"));layout->addWidget(upgrade);connect(upgrade,&QPushButton::clicked,this,[this]{garageShop();});auto documents=button(QStringLiteral("Договоры купли-продажи"));layout->addWidget(documents);connect(documents,&QPushButton::clicked,this,[this]{documentsApp();});auto summary=new QLabel;summary->setWordWrap(true);layout->addWidget(summary);auto scroll=new QScrollArea;scroll->setWidgetResizable(true);auto list=new QWidget;auto rows=new QVBoxLayout(list);scroll->setWidget(list);layout->addWidget(scroll);auto refresh=[this,summary,rows]{if(closing||!session||!session->ready())return;while(auto item=rows->takeAt(0)){delete item->widget();delete item;}const auto& state=session->state;summary->setText(QStringLiteral("Автомобилей: %1 · Мест в гараже: %2").arg(qulonglong(state.at("garage").size())).arg(state.value("garageCapacity",1)));for(const auto& id:state.at("garage")){auto card=new QFrame;card->setObjectName("garageCard");auto carRows=new QVBoxLayout(card);carRows->setContentsMargins(16,16,16,16);carRows->setSpacing(10);rows->addWidget(card);auto key=std::to_string(id.get<perekup::Money>());if(!carsById.contains(key))continue;if(!carsById[key].contains("commerceOffer")){auto image=photoOverrides.value(key,carsById[key].value("img",""));auto photo=new CarPhotoView(root+"/assets/"+qs(image),photoCrops.value(image,Json()),512,true);carRows->addWidget(photo);}auto label=new QLabel(qs(carsById[key].value("name","")));label->setStyleSheet("font-size:14px;font-weight:600");label->setWordWrap(true);carRows->addWidget(label);if(carsById[key].contains("commerceOffer")){carRows->addWidget(commercePhoto(carsById[key]));carRows->addWidget(new QLabel(QStringLiteral("Заводской цвет: ")+qs(perekup::nativeFactoryColorInfo(perekup::nativeFactoryColor(state,carsById[key],offersById))->name)));}const auto& vehicles=state.at("transport").at("vehicles");if(vehicles.contains(key)){const auto& v=vehicles[key];auto city=v.value("cityId",homeCity);auto text=citiesById.contains(city)?qs(citiesById[city].value("name","")):QString();if(perekup::num(v,"debt"))text+=QStringLiteral(" · Долг за парковку: ")+money(perekup::num(v,"debt"));carRows->addWidget(new QLabel(text));auto carId=id.get<perekup::Money>();auto repair=button(QStringLiteral("Ремонт и диагностика"));carRows->addWidget(repair);connect(repair,&QPushButton::clicked,this,[this,carId]{repairApp(carId);});auto sell=button(QStringLiteral("Объявление и покупатели"));carRows->addWidget(sell);connect(sell,&QPushButton::clicked,this,[this,carId]{saleApp(carId);});if(perekup::num(v,"debt")>0){auto pay=button(QStringLiteral("Оплатить парковку"));carRows->addWidget(pay);connect(pay,&QPushButton::clicked,this,[this,carId]{garageTransport(carId,false);});}auto place=v.value("place","");if(place=="carrier")carRows->addWidget(new QLabel(QStringLiteral("Автомобиль в пути на автовозе")));else if(city!=homeCity&&place!="road"){auto quote=perekup::shippingQuote(citiesById.at(city),citiesById.at(homeCity),false);if(quote.is_object()){auto ship=button(QStringLiteral("Автовоз домой · ")+money(perekup::num(quote,"price")));carRows->addWidget(ship);connect(ship,&QPushButton::clicked,this,[this,carId]{garageTransport(carId,true);});}}}}if(state.at("garage").empty())rows->addWidget(new QLabel(QStringLiteral("Пока нет автомобилей.")));rows->addStretch();};auto timer=new QTimer(body);connect(timer,&QTimer::timeout,body,refresh);timer->start(2000);refresh();open("garage",QStringLiteral("Гараж"),body,QSize(820,720));}
 void adminApp(){
 if(!session||!session->ready())return;
 if(!adminUnlocked){if(QDateTime::currentMSecsSinceEpoch()<adminLockUntil){showError(QStringLiteral("Подождите 15 секунд перед новой попыткой."));return;}bool ok=false;auto password=QInputDialog::getText(this,QStringLiteral("Админ-панель"),QStringLiteral("Пароль"),QLineEdit::Password,QString(),&ok);if(!ok)return;if(perekup::hashStr("perekyp:"+password.toUtf8().toStdString())!=1979982443587708ULL){if(++adminFailures>=3){adminFailures=0;adminLockUntil=QDateTime::currentMSecsSinceEpoch()+15000;}showError(QStringLiteral("Неверный пароль."));return;}adminFailures=0;adminUnlocked=true;}
 auto body=new QWidget;auto layout=new QVBoxLayout(body);auto status=new QLabel(QStringLiteral("Перемотка обрабатывает платежи, встречи, перевозки и коллекторов. При звонке она остановится, чтобы вы могли ответить."));status->setWordWrap(true);layout->addWidget(status);auto skip=button(QStringLiteral("Пропустить день · +24 часа"));layout->addWidget(skip);connect(skip,&QPushButton::clicked,body,[this,status]{if(collectorDialogOpen||closing||runtimeFailed)return;try{auto draft=session->state;auto hooks=runtimeHooks();auto result=perekup::skipNativeDay(draft,[&](Json& staged,perekup::Money next){perekup::tickRuntime(staged,next,citiesById,carsById,offersById,homeCity,hooks);});if(result.advanced>0){session->commit(draft);syncCareerMarket();gameClock.gameMs=session->state.at("gameMs").get<qint64>();gameClock.lastRealMs=QDateTime::currentMSecsSinceEpoch();}status->setText(result.completed?QStringLiteral("Пропущен один игровой день. Результат сохранён."):result.blocked=="call"?QStringLiteral("Перемотка остановлена звонком коллектора. Завершите разговор и при необходимости снова пропустите день."):QStringLiteral("Перемотка недоступна: игра завершена."));if(result.blocked=="call")collectorCall();}catch(const std::exception& e){status->setText(QStringLiteral("Перемотка не сохранена: ")+QString::fromUtf8(e.what()));}});auto amount=new QLineEdit("100000");amount->setValidator(new QRegularExpressionValidator(QRegularExpression("[0-9]{1,16}"),amount));layout->addWidget(new QLabel(QStringLiteral("Управление балансом, ₽")));layout->addWidget(amount);
 for(const auto& action:std::vector<std::pair<std::string,QString>>{{"add",QStringLiteral("Добавить деньги")},{"sub",QStringLiteral("Списать деньги")},{"set",QStringLiteral("Установить баланс")}}){auto b=button(action.second);layout->addWidget(b);connect(b,&QPushButton::clicked,body,[this,status,amount,mode=action.first]{if(closing||collectorDialogOpen)return;bool valid=false;auto value=amount->text().toLongLong(&valid);if(!valid||value<0){status->setText(QStringLiteral("Введите целую неотрицательную сумму."));return;}try{auto draft=session->state;if(perekup::nativeAdminMoney(draft,mode,value,[&](const Json& saved){session->commit(saved);}))status->setText(QStringLiteral("Баланс сохранён: ")+money(perekup::num(session->state,"balance")));else status->setText(QStringLiteral("Операция недоступна."));}catch(const std::exception& e){status->setText(QString::fromUtf8(e.what()));}});}
 auto garage=new QComboBox;for(auto cap:{1,5,8,12,20})garage->addItem(QStringLiteral("Мест в гараже: %1").arg(cap));layout->addWidget(garage);auto applyGarage=button(QStringLiteral("Установить уровень гаража"));layout->addWidget(applyGarage);connect(applyGarage,&QPushButton::clicked,body,[this,status,garage]{try{auto draft=session->state;if(perekup::nativeAdminGarage(draft,garage->currentIndex(),citiesById,carsById,homeCity,[&](const Json& saved){session->commit(saved);}))status->setText(QStringLiteral("Вместимость гаража сохранена. Машины не удалялись."));}catch(const std::exception& e){status->setText(QString::fromUtf8(e.what()));}});
 auto lock=button(QStringLiteral("Заблокировать админ-панель"));layout->addWidget(lock);connect(lock,&QPushButton::clicked,body,[this]{adminUnlocked=false;auto it=windows.find("admin");if(it!=windows.end())it->second->close();});layout->addStretch();open("admin",QStringLiteral("Админ-панель"),body,QSize(500,650));
 }
