 void settings(){auto body=new QWidget;auto outer=new QVBoxLayout(body);auto scroll=new QScrollArea;scroll->setWidgetResizable(true);auto content=new QWidget;auto sections=new QVBoxLayout(content);sections->setContentsMargins(22,22,22,22);sections->setSpacing(16);auto section=[sections](const QString& title){auto card=new QFrame;card->setObjectName("settingsCard");auto layout=new QVBoxLayout(card);layout->setContentsMargins(16,16,16,16);layout->setSpacing(12);auto heading=new QLabel(title);heading->setObjectName("heading");layout->addWidget(heading);sections->addWidget(card);return layout;};auto l=section(QStringLiteral("Ваш профиль"));auto profile=new QLabel;profile->setObjectName("settingsProfile");profile->setStyleSheet("font-size:22px;font-weight:600");profile->setText(session&&session->ready()?qs(session->state["playerIdentity"].value("nickname","")):QStringLiteral("Игрок"));auto profileRow=new QHBoxLayout;auto avatar=new QLabel(profile->text().left(1).toUpper());avatar->setAlignment(Qt::AlignCenter);avatar->setFixedSize(70,70);avatar->setStyleSheet("background:#dcebe5;color:#14796f;border-radius:8px;font-size:28px;font-weight:600;");profileRow->addWidget(avatar);profileRow->addWidget(profile,1);l->addLayout(profileRow);l=section(QStringLiteral("Оформление"));addThemeSettings(l,body);l=section(QStringLiteral("Язык и музыка"));scroll->setWidget(content);outer->addWidget(scroll);addUserSettings(l,body);l=section(QStringLiteral("Динамический остров"));addIslandSettings(l,body);l=section(QStringLiteral("Экран и оформление"));auto resolutions=new QComboBox;for(const auto& size:displaySizes())resolutions->addItem(QString("%1 × %2").arg(size.width()).arg(size.height()),size);auto remembered=QSize(preferences.value("resolutionWidth").toInt(1280),preferences.value("resolutionHeight").toInt(720));auto savedIndex=resolutions->findData(remembered);if(savedIndex>=0)resolutions->setCurrentIndex(savedIndex);l->addWidget(resolutions);auto fullscreen=button(QStringLiteral("Полный экран")),windowed=button(QStringLiteral("Оконный режим"));l->addWidget(fullscreen);l->addWidget(windowed);auto recommendation=new QLabel;recommendation->setWordWrap(true);l->addWidget(recommendation);auto hint=[resolutions,recommendation]{auto size=resolutions->currentData().toSize();recommendation->setText(QStringLiteral("Для чётких обоев используйте изображение %1 × %2 пикселей.").arg(size.width()).arg(size.height()));};connect(resolutions,qOverload<int>(&QComboBox::currentIndexChanged),this,hint);hint();connect(fullscreen,&QPushButton::clicked,this,[this,resolutions]{applyDisplay(true,resolutions->currentData().toSize());});connect(windowed,&QPushButton::clicked,this,[this,resolutions]{applyDisplay(false,resolutions->currentData().toSize());});l=section(QStringLiteral("Обои рабочего стола"));for(const auto& item:std::vector<std::pair<QString,QString>>{{QStringLiteral("Набережная"),"assets/wallpapers/embankment.webp"},{QStringLiteral("Сияние"),"assets/wallpapers/ribbons.jpg"}}){auto preset=button(item.first);l->addWidget(preset);connect(preset,&QPushButton::clicked,this,[this,path=item.second]{auto previous=preferences;preferences["wallpaper"]=path;if(!savePreferences()){preferences=previous;showError(QStringLiteral("Не удалось сохранить настройки обоев."));return;}desktop->setWallpaper(root+"/"+path);});}auto wallpaper=button(QStringLiteral("Загрузить свои обои"));l->addWidget(wallpaper);connect(wallpaper,&QPushButton::clicked,this,[this]{auto path=QFileDialog::getOpenFileName(this,QStringLiteral("Выберите обои"),QString(),"Images (*.png *.jpg *.jpeg *.webp)");if(path.isEmpty())return;QPixmap image(path);if(image.isNull()){showError(QStringLiteral("Не удалось открыть изображение."));return;}QDir().mkpath(root+"/saves");QSaveFile file(root+"/saves/wallpaper.png");if(!file.open(QIODevice::WriteOnly)||!image.save(&file,"PNG")||!file.commit()){showError(QStringLiteral("Не удалось сохранить обои."));return;}preferences["wallpaper"]="saves/wallpaper.png";if(!savePreferences()){showError(QStringLiteral("Не удалось сохранить настройки."));return;}desktop->setWallpaper(root+"/saves/wallpaper.png");});l=section(QStringLiteral("Дополнительно"));auto resetLayout=button(QStringLiteral("Вернуть ярлыки на исходные места"));l->addWidget(resetLayout);connect(resetLayout,&QPushButton::clicked,this,[this]{auto old=preferences;preferences.remove("shortcutPositions");if(!savePreferences()){preferences=old;showError(QStringLiteral("Не удалось сохранить расположение ярлыков."));return;}const QStringList ids={"market","garage","travel","bank","documents","calendar","calc","clock"};for(int i=0;i<ids.size();++i)if(auto shortcut=findChild<QToolButton*>("shortcut-"+ids[i]))shortcut->move(24+(i%2)*102,78+(i/2)*102);positionDock();});auto admin=button(QStringLiteral("Админ-панель"));l->addWidget(admin);connect(admin,&QPushButton::clicked,this,[this]{adminApp();});l->addStretch();open("settings",QStringLiteral("Настройки"),body,QSize(860,720));}

