 void runStartupFeatures(){startUserFeatures();}
 void careerSmokeTest(){try{perekup::Money id=0;for(const auto& car:catalog["cars"])if(car.value("cityId",homeCity)==homeCity&&perekup::basePrice(car)<=100000&&perekup::num(perekup::nativeCarStory(car),"repair")>0){id=car.at("id");break;}if(!id)throw std::runtime_error("No repair test car");auto draft=session->state;perekup::nativeAdminMoney(draft,"set",1000000,[](const Json&){});perekup::Deals deals(citiesById,carsById,homeCity,[]{return .9;});auto result=deals.plan(draft,"buy",id,80000);if(!result.ok)throw std::runtime_error(result.error);perekup::applyCareerDealEffects(result.state,result.effects,carsById);session->commit(result.state);repairApp(id);auto repair=windows.at(qs("repair-"+std::to_string(id)));bool clicked=false;for(auto b:repair->findChildren<QPushButton*>())if(b->text()==QStringLiteral("Диагностика · 1 500 ₽")){b->click();clicked=true;break;}if(!clicked||!session->state["career"]["vehicles"][std::to_string(id)].value("inspected",false))throw std::runtime_error("Repair GUI diagnosis failed");for(auto b:repair->findChildren<QPushButton*>())if(b->text().startsWith(QStringLiteral("Устранить износ"))){b->click();break;}if(!session->state["career"]["vehicles"][std::to_string(id)].value("repaired",false))throw std::runtime_error("Repair GUI preparation failed");businessApp();commerceApp();qInfo()<<"Career GUI: diagnosis, preparation, business and supply windows opened";auto order=session->state["career"]["orders"][0]["id"].get<std::string>();auto staged=session->state;if(!perekup::nativeCareerAction(staged,"accept",order,citiesById,carsById,homeCity,[&](const Json& saved){session->commit(saved);}))throw std::runtime_error("GUI test accept order");auto autoSign=new QTimer(this);connect(autoSign,&QTimer::timeout,this,[autoSign]{auto modal=QApplication::activeModalWidget();if(!modal)return;if(auto box=qobject_cast<QMessageBox*>(modal)){box->accept();autoSign->stop();return;}auto dialog=qobject_cast<QDialog*>(modal);if(!dialog||dialog->windowTitle()!=QStringLiteral("Договор с клиентом"))return;auto signature=dialog->findChild<QLineEdit*>();auto ack=dialog->findChild<QCheckBox*>();if(!signature||!ack)return;signature->setText("TEST");ack->setChecked(true);for(auto b:dialog->findChildren<QPushButton*>())if(b->text()==QStringLiteral("Подписать и передать")){QTimer::singleShot(200,[]{if(auto box=qobject_cast<QMessageBox*>(QApplication::activeModalWidget()))box->accept();});b->click();break;}});autoSign->start(100);QTimer::singleShot(100,this,[this,order,id,autoSign]{clientDelivery(order,id);autoSign->stop();autoSign->deleteLater();if(session->state["contracts"]["records"].empty()||!session->state["garage"].empty()){qWarning()<<"Client GUI signature failed";QApplication::exit(18);return;}qInfo()<<"Career GUI: client signature, payment, ownership and DKP passed";QTimer::singleShot(250,this,[this]{auto shot=qEnvironmentVariable("PEREKYP_CAREER_SCREENSHOT");if(!shot.isEmpty()&&!grab().save(shot)){QApplication::exit(19);return;}close();});});}catch(const std::exception& e){qWarning()<<e.what();QApplication::exit(17);}}
